UPDATE org_presidents
SET photo_url  = #{photoUrl},
    photo_type = #{photoType}
WHERE president_id = #{presidentId}
  AND state = 'normal'

mapper.select:
SELECT COUNT(*)
FROM org_members
WHERE president_id = #{presidentId}
  AND term_label = #{term}
  AND state = 'normal'

