UPDATE org_members
SET state = 'deleted'
WHERE president_id = #{presidentId}
  AND term_label = #{term}
  AND state = 'normal'

UPDATE org_members
SET term_label = #{to}
WHERE president_id = #{presidentId}
  AND term_label = #{from}
  AND state = 'normal'
